def uniquePathsIII(grid: list[list[int]]) -> int:
    m, n = len(grid), len(grid[0])
    empty = 1
    start = (0, 0)
    for r in range(m):
        for c in range(n):
            if grid[r][c] == 0: empty += 1
            elif grid[r][c] == 1: start = (r, c)
    paths = 0
    def dfs(r, c, remain):
        nonlocal paths
        if grid[r][c] == 2:
            if remain == 0: paths += 1
            return
        temp = grid[r][c]
        grid[r][c] = -1
        for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < m and 0 <= nc < n and grid[nr][nc] != -1:
                dfs(nr, nc, remain - 1)
        grid[r][c] = temp
    dfs(start[0], start[1], empty)
    return paths

